            v(13,0) = qcx*v(3,0) + wqx*v(3,1)
            v(14,0) = qcx*v(4,0) + wqx*v(4,1)
            v(24,0) = paz*v(21,0) + wpz*v(21,1)
            v(34,0) = paz*v(31,0) + wpz*v(31,1) &
