            v(27,1) = pax*v(24,1) + wpx*v(24,0)
            v(35,1) = qcz*v(5,1) + wqz*v(5,0)
            v(40,1) = paz*v(34,1) + wpz*v(34,0) &
               + 1.0_dp*oo2z*(v(31,1) - rz*v(31,0)) &
               + 1.0_dp*oo2ze*v(4,0)
            v(42,1) = qcx*v(12,1) + wqx*v(12,0) &
